-- Irene Ingram (profileID=9) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Irene Ingram phrasings

SELECT p.argumentID, p.phrasingID, 9, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 9
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 9 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=9 AND targArgID IN (101,103,105,107,123,124,125,127,128,129,140,141,142,144,145,148,153,154,175,217,288,293,294,295,297,315,316,321,414,476,477,484,485,494,495,496,539,543,544,561,696,698,699,700,701,702,785,790,791,792,795,797,801,863,892,895,896,897,898,901,910,911,958,964,975,977,998,1177,1179,1180,1200,1201,1275,1276,1296,1298,1300,1312,1425,1498,1523);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 9
SET pe.active = o.acceptance
WHERE pe.profileID = 9;

SELECT 'Done: endorsements for profileID=9' AS status;